import { useEffect } from "react";
import * as THREE from "three";
import { useAppContext } from "../context/AppContext";

export function useThreeJS(containerRef) {
  const { state } = useAppContext();
  useEffect(() => {
    if (!containerRef.current) return;

    // Add a simple overlay div (step toward overlays)
    let overlayDiv = document.createElement("div");
    overlayDiv.innerText = "Overlay Test";
    overlayDiv.style.position = "absolute";
    overlayDiv.style.top = "20px";
    overlayDiv.style.left = "20px";
    overlayDiv.style.color = "white";
    overlayDiv.style.background = "rgba(0,0,0,0.5)";
    overlayDiv.style.padding = "8px";
    overlayDiv.style.borderRadius = "8px";
    overlayDiv.style.zIndex = "10";
    overlayDiv.id = "threejs-overlay-test";
    containerRef.current.appendChild(overlayDiv);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x000011);
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );

    if (state && state.camera && state.camera.position) {
      camera.position.set(
        state.camera.position.x,
        state.camera.position.y,
        state.camera.position.z
      );
    } else {
      camera.position.z = 5;
    }

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000011, 1);
    containerRef.current.appendChild(renderer.domElement);

    const geometry = new THREE.SphereGeometry(2, 32, 32);
    const material = new THREE.MeshBasicMaterial({ color: 0xff0000 });
    const sphere = new THREE.Mesh(geometry, material);
    scene.add(sphere);

    let animationId;
    function animate() {
      animationId = requestAnimationFrame(animate);
      if (state && state.animation && state.animation.isPlaying) {
        sphere.rotation.y += 0.01;
      }
      renderer.render(scene, camera);
    }
    animate();

    return () => {
      if (
        containerRef.current &&
        renderer.domElement &&
        containerRef.current.contains(renderer.domElement)
      ) {
        containerRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
      cancelAnimationFrame(animationId);

      if (
        containerRef.current &&
        overlayDiv &&
        containerRef.current.contains(overlayDiv)
      ) {
        containerRef.current.removeChild(overlayDiv);
      }
    };
  }, [containerRef, state && state.camera && state.camera.position]);
}
